def prf(preds, golds):
    tp=sum(p and g for p,g in zip(preds,golds)); fp=sum(p and not g for p,g in zip(preds,golds))
    fn=sum(not p and g for p,g in zip(preds,golds)); tn=sum(not p and not g for p,g in zip(preds,golds))
    P=tp/max(1,tp+fp); R=tp/max(1,tp+fn)
    return {"P":round(P,3),"R":round(R,3),"F1":round(2*P*R/max(1e-9,P+R),3)}

golds=[p["label"] for p in PAIRS]; half=len(PAIRS)//2
def tuned_apply(scores):
    best=None
    qs=sorted(set(scores)); import numpy as np
    for th in [min(scores)+i*(max(scores)-min(scores))/20 for i in range(1,20)]:
        preds=[s>=th for s in scores[:half]]
        r=prf(preds,golds[:half])
        if best is None or r["F1"]>best[1]["F1"]: best=(th,r)
    th=best[0]; test=prf([s>=th for s in scores[half:]], golds[half:])
    return {"threshold":round(th,4),"train":best[1],"test":test}

# --- embedder arms
from sentence_transformers import SentenceTransformer, util
for name,mid in [("bge-large","BAAI/bge-large-en-v1.5"),("e5-large","intfloat/e5-large-v2")]:
    try:
        t0=time.time()
        try:
            m=SentenceTransformer(mid, device="cuda" if torch.cuda.is_available() else "cpu")
            m.encode(["probe"], show_progress_bar=False)
        except Exception:
            print("cuda embed fail, cpu fallback", flush=True)
            m=SentenceTransformer(mid, device="cpu")
        qe=m.encode([PROBLEMS[p["pid"]] for p in PAIRS], normalize_embeddings=True, batch_size=32, show_progress_bar=False)
        de=m.encode([p["title"] for p in PAIRS], normalize_embeddings=True, batch_size=32, show_progress_bar=False)
        import numpy as np
        scores=(qe*de).sum(1).tolist()
        OUT[name]={"load_s":round(time.time()-t0,1),**tuned_apply(scores)}
        print(name, OUT[name], flush=True)
    except Exception as e: OUT[name]={"error":str(e)[:120]}

# --- GLiNER 2.5 arm
try:
    from gliner import GLiNER
    t0=time.time(); gid=None
    for cand in ["urchade/gliner_large-v2.5","urchade/gliner_largev2.5","urchade/gliner_largev2","gliner-community/gliner_multi_pile-v1"]:
        try:
            g=GLiNER.from_pretrained(cand); gid=cand; break
        except Exception as e:
            print("gliner cand fail:",cand,str(e)[:60],flush=True)
    if gid is None: raise RuntimeError("no gliner model available")
    scores=[]
    for p in PAIRS:
        text="Problem: "+PROBLEMS[p["pid"]]+" Document: "+p["title"]
        ents=g.predict_entities(text, ["relevant engineering evidence for the problem"], threshold=0.0)
        scores.append(max([e["score"] for e in ents], default=0.0))
    OUT["gliner2.5-large"]={"model":gid,"load_s":round(time.time()-t0,1),"n_pairs":len(scores),**tuned_apply(scores)}
    print("gliner", OUT["gliner2.5-large"], flush=True)
except Exception as e:
    OUT["gliner2.5-large"]={"error":str(e)[:200]}

# --- Qwen pure-vs-hybrid synthesis (7B, fallback 3B)
try:
    from transformers import AutoModelForCausalLM, AutoTokenizer
    import torch
    model_id="Qwen/Qwen2.5-7B-Instruct"
    cuda_ok=torch.cuda.is_available()
    if cuda_ok:
        try:
            tok=AutoTokenizer.from_pretrained(model_id); mod=AutoModelForCausalLM.from_pretrained(model_id, torch_dtype=torch.float16, device_map="auto")
            mod.generate(torch.tensor([[1]]).to(mod.device), max_new_tokens=1)
        except Exception as e:
            print("cuda gen probe fail:", str(e)[:80], flush=True); cuda_ok=False
    if not cuda_ok:
        try:
            del mod; torch.cuda.empty_cache()
        except Exception:
            pass
        model_id="Qwen/Qwen2.5-1.5B-Instruct"
        try:
            tok=AutoTokenizer.from_pretrained(model_id)
            mod=AutoModelForCausalLM.from_pretrained(model_id, torch_dtype=torch.float32, device_map="cpu")
        except Exception:
            model_id="Qwen/Qwen2.5-0.5B-Instruct"
            tok=AutoTokenizer.from_pretrained(model_id)
            mod=AutoModelForCausalLM.from_pretrained(model_id, torch_dtype=torch.float32, device_map="cpu"); mod=AutoModelForCausalLM.from_pretrained(model_id, torch_dtype=torch.float32)
    OUT["synth_model"]=model_id
    def gen(prompt):
        msgs=[{"role":"system","content":"You are a mechanism interpreter for engineering problem-solving."},{"role":"user","content":prompt}]
        t0=time.time()
        inp=tok.apply_chat_template(msgs, add_generation_prompt=True, return_tensors="pt").to(mod.device)
        out=mod.generate(inp, max_new_tokens=220, do_sample=False)
        txt=tok.decode(out[0][inp.shape[1]:], skip_special_tokens=True)
        return txt, round(time.time()-t0,1)
    FIELDS=["MECHANISM:","INTERVENTION:","EXPECTED_EFFECT:","FALSIFICATION_TEST:","MECHANISM_SOURCE_SPAN:"]
    DOMKW={"wind":["erosion","coating","leading edge","rain","blade"],"hemo":["catheter","thromb","heparin","fibrin","patency"],"pouch":["lithium","battery","cell","gas","electrolyte"]}
    synth={}
    for pid in ["wind","hemo","pouch"]:
        for mode in ["pure","hybrid"]:
            base=f"DEVICE FAILURE:\n{PROBLEMS[pid]}\n"
            docs=TOP_DOCS.get(pid,[]) if mode=="hybrid" else []
            if mode=="hybrid" and not docs: continue
            if docs: base+="\nRETRIEVED EVIDENCE:\n" + "\n---\n".join("Title: "+d for d in docs) + "\nRespond EXACTLY with fields MECHANISM/INTERVENTION/EXPECTED_EFFECT/FALSIFICATION_TEST/MECHANISM_SOURCE_SPAN (span = verbatim words from one title)."
            else: base+="\nRespond EXACTLY with fields MECHANISM/INTERVENTION/EXPECTED_EFFECT/FALSIFICATION_TEST."
            txt,lat=gen(base)
            filled=sum(1 for f in FIELDS if f in txt)
            grounded=any(span_found in " ".join(docs).lower() for span_found in [l.split("MECHANISM_SOURCE_SPAN:")[-1].strip().lower()[:60]] ) if docs else False
            domhit=any(k in txt.lower() for k in DOMKW[pid])
            synth[f"{pid}:{mode}"]={"latency_s":lat,"fields":filled,"grounded":grounded,"domain_keyword_hit":domhit,"mechanism":txt[:150]}
            print(pid,mode,synth[f"{pid}:{mode}"], flush=True)
    OUT["synth_pure_vs_hybrid"]=synth
except Exception as e:
    OUT["synth_pure_vs_hybrid"]={"error":repr(e)[:250]}

def lexscore(a,b):
    STOP=set("a an the of to in on for with and or is are was were be been it its this that from by at as into not no but if then than so such can may might will would must have has had do does did using used based via new why how".split())
    tk=lambda s:{w for w in re.findall(r"[a-z]{3,}",s.lower()) if w not in STOP}
    x,y=tk(a),tk(b)
    return len(x&y)/max(1,min(len(x),len(y)))
preds=[lexscore(PROBLEMS[p["pid"]],p["title"])>=0.10 for p in PAIRS]; golds2=[p["label"] for p in PAIRS]
tp=sum(p and g for p,g in zip(preds,golds2)); fp=sum(p and not g for p,g in zip(preds,golds2)); fn=sum(not p and g for p,g in zip(preds,golds2))
OUT["lexical@0.10_kernel"]={"P":round(tp/max(1,tp+fp),3),"R":round(tp/max(1,tp+fn),3),"F1":round(2*tp/max(1,2*tp+fp+fn),3)}
json.dump(OUT, open("/kaggle/working/results_kernel.json","w"), indent=1)
print("KERNEL DONE")
